// Block (composition) — a trip from one place to another, partway done: a flight, a delivery.
// Card owns the surface, ProgressBar the bar, Badge the status; Stack arranges.
import { useId } from "react";
import type { Ref } from "react";
import type { BadgeProps } from "../components/Badge";
import { Badge } from "../components/Badge";
import { Card } from "../components/Card";
import { ProgressBar } from "../components/ProgressBar";
import { Stack } from "../layouts/Stack";
import "./RouteProgress.css";

export interface RouteProgressEndpoint {
  /** The short code that names the place ("SMX"). */
  code: string;
  /** The place written out ("Santa Maria"). */
  label?: string;
  /** When the trip leaves or reaches it ("9:40 AM"). */
  time?: string;
}

export interface RouteProgressProps {
  /** Where the trip started. */
  origin: RouteProgressEndpoint;
  /** Where it is going. */
  destination: RouteProgressEndpoint;
  /** How far along it is, 0 to 100. */
  value: number;
  /** Names the progress bar for assistive tech ("Flight progress"). */
  progressLabel: string;
  /** What is left, as it should read ("1 h 12 min left"). */
  remaining?: string;
  /** The trip's status. Its variant follows the Badge law: `error` for a delay, `live` while
   *  it is moving, `neutral` otherwise. A trip status is never `strong`, so the type leaves it out. */
  status?: { label: string; variant?: Extract<BadgeProps["variant"], "neutral" | "live" | "error"> };
  className?: string;
  ref?: Ref<HTMLElement>;
}

function Endpoint({ endpoint, align }: { endpoint: RouteProgressEndpoint; align: "start" | "end" }) {
  return (
    <Stack gap="2x-small" align={align} className="sd-routeprogress__endpoint">
      <span className="sd-routeprogress__code sd-type-headline-medium">{endpoint.code}</span>
      {endpoint.label && (
        <span className="sd-routeprogress__place sd-type-body-medium">{endpoint.label}</span>
      )}
      {endpoint.time && (
        <span className="sd-routeprogress__time sd-type-caption-medium">{endpoint.time}</span>
      )}
    </Stack>
  );
}

export function RouteProgress({
  origin,
  destination,
  value,
  progressLabel,
  remaining,
  status,
  className,
  ref,
}: RouteProgressProps) {
  const routeId = useId();
  return (
    <Card className={className ? `sd-routeprogress ${className}` : "sd-routeprogress"}>
      <Stack as="section" ref={ref} aria-labelledby={routeId} gap="medium" className="sd-routeprogress__content">
        {/* The route names the section: "SMX to LAX", read from the two codes. */}
        <span id={routeId} className="sd-visually-hidden">
          {`${origin.code} to ${destination.code}`}
        </span>
        {/* The row spans the Card: the origin reads from the start edge, the destination from the end. */}
        <>
          <Stack direction="row" justify="between" align="start" gap="medium" className="sd-routeprogress__endpoints">
            <Endpoint endpoint={origin} align="start" />
            <Endpoint endpoint={destination} align="end" />
          </Stack>
        </>
        <ProgressBar aria-label={progressLabel} value={value} />
        {(remaining || status) && (
          <Stack direction="row" justify="between" align="center" gap="small" className="sd-routeprogress__footer">
            {remaining && (
              <>
                <span className="sd-routeprogress__remaining sd-type-body-medium">{remaining}</span>
              </>
            )}
            {status && (
              <Badge variant={status.variant ?? "neutral"} className="sd-routeprogress__status">
                {status.label}
              </Badge>
            )}
          </Stack>
        )}
      </Stack>
    </Card>
  );
}

/* RouteProgress.css — .sd-routeprogress (Block)
   Arrangement only: Card owns the surface, ProgressBar and Badge their look. */
.sd-routeprogress__endpoint {
  min-width: 0;
}

/* The destination reads from the far edge, so its lines align to the end. */
.sd-routeprogress__endpoint:last-child {
  text-align: end;
}

.sd-routeprogress__code,
.sd-routeprogress__time,
.sd-routeprogress__remaining {
  font-variant-numeric: tabular-nums;
}

.sd-routeprogress__status {
  flex: none;
}
